detaileddescription.para:
Example demonstrating how to solve a block tridiagonal system in parallel


The system has the form                 \[\begin{pmatrix}
M_0 & \tp{K_0} & 0 & 0 & \cdots & K_{N-1} \\
K_0 & M_1 & \tp{K_1} & 0 & \cdots & 0 \\
0 & K_1 & M_2 & \tp{K_2} & \cdots & 0 \\
0 & 0 & K_2 & M_3 & \cdots & 0 \\
\vdots & \vdots & \vdots & \vdots & \ddots & \vdots \\
\tp{K_{N-1}} & 0 & 0 & 0 & \cdots & M_{N-1}
\end{pmatrix}
\begin{pmatrix}
x^0 \\ x^1 \\ x^2 \\ x^3 \\ \vdots \\ x^{N-1}
\end{pmatrix}
=
\begin{pmatrix}
b^0 \\ b^1 \\ b^2 \\ b^3 \\ \vdots \\ b^{N-1}
\end{pmatrix}
\]

The example also demonstrates how to perform a factorization update, which is useful when solving a sequence of related systems. The coefficient matrix is updated by the term                          \[\begin{pmatrix}
B_0^{\phantom\top} & 0 & 0 & 0 & \cdots & F_{N-1}^{\phantom\top} \\
F_0^{\phantom\top} & B_1^{\phantom\top} & 0 & 0 & \cdots & 0 \\
0 & F_1^{\phantom\top} & B_2^{\phantom\top} & 0 & \cdots & 0 \\
0 & 0 & F_2^{\phantom\top} & B_3^{\phantom\top} & \cdots & 0 \\
\vdots & \vdots & \vdots & \vdots & \ddots & \vdots \\
0 & 0 & 0 & 0 & F_{N-2}^{\phantom\top} & B_{N-1}^{\phantom\top}
\end{pmatrix}
\begin{pmatrix}
S_0^{\phantom\top} \\
& S_1^{\phantom\top} \\
&& S_2^{\phantom\top} \\
&&& S_3^{\phantom\top} \\
&&&& \ddots \\
&&&&& S_{N-1}^{\phantom\top}
\end{pmatrix}
\begin{pmatrix}
B_0^\top & F_0^\top & 0 & 0 & \cdots & 0 \\
0 & B_1^\top & F_1^\top & 0 & \cdots & 0 \\
0 & 0 & B_2^\top & F_2^\top & \cdots & 0 \\
0 & 0 & 0 & B_3^\top & \cdots & 0 \\
\vdots & \vdots & \vdots & \vdots & \ddots & F_{N-2}^\top \\
F_{N-1}^\top & 0 & 0 & 0 & \cdots & B_{N-1}^\top
\end{pmatrix}
\] #include<batmat/matrix/matrix.hpp>
#include<fancyqlone/cyqlone/cyqlone.hpp>
#include<fancyqlone/packing.hpp>
#include<guanaqo/blas/hl-blas-interface.hpp>
#include<guanaqo/print.hpp>
#include<algorithm>
#include<iostream>
#include<random>
#include<string>

#ifCYQLONE_WITH_MATIO
#include<fancyqlone/matio.hpp>
#endif

usingfancyqlone::index_t;//Integertypeforindices
usingfancyqlone::real_t;//Floating-pointtypeforscalars
usingmatrices=batmat::matrix::Matrix<real_t, index_t>;//Arrayofmatrices

constexprindex_tv=4;//Vectorlengthtouse
usingTricyqleSolver=fancyqlone::TricyqleSolver<v, real_t>;//Blocktridiagonalsolvertouse

structTridiagSystem{
matricesM,K,b;//DiagonalblocksM,subdiagonalblocksKandright-handsideb
};

structBidiagUpdate{
matricesB,F;//Diagonalandsubdiagonalblocksoftheupdatematrices
matricesS;//DiagonalmatricesΣ
};

//GeneratearandomSPDblocktridiagonalsystemwithgivenblocksizeandnumberofblocks.
TridiagSysteminit_random_system(index_tblock_size,index_tnum_blocks,boolcircular=false);
//Generatearandombidiagonalupdatematrixfortheblocktridiagonalsystem.
BidiagUpdateinit_random_update(index_tblock_size,index_tnum_blocks,index_trank,
boolcircular=false);

//ExampleofsolvingablocktridiagonalsystemusingtheTricyqleSolver.
intmain(intargc,char*argv[])try{
//Problemdimensionsandparameters
index_tp=8;//Numberofprocessors/threads
index_tblock_size=5;//Sizeofeachblockoftheblocktridiagonalsystem
boolcircular=false;//IsK(num_blocks-1)nonzero?
index_trank=2;//Rankforthefactorizationupdates
//Parsearguments
if(argc>1)
p=std::stoi(argv[1]);
if(argc>2)
block_size=std::stoi(argv[2]);
if(argc>3)
circular=std::stoi(argv[3])!=0;
if(argc>4)
rank=std::stoi(argv[4]);
//Thenumberofblocksintheblocktridiagonalsystemalwaysequalsp*v.Ifyoursystemis
//larger,firstreduceittothissize(inparallel).Ifitissmaller,manuallyaddpadding,
//orreducepand/orv.
BATMAT_ASSERT(fancyqlone::is_pow_2(p));
constindex_tnum_blocks=p*v;

//DiagonalblocksM,subdiagonalblocksKandright-handsidebofablocktridiagonalsystem
auto[M,K,b]=init_random_system(block_size,num_blocks,circular);

//Createasolverfortheblocktridiagonalsystem
TricyqleSolversolver{
.block_size=block_size,.max_rank=p*rank,.circular=circular,.p=p};
solver.params.solve_method=fancyqlone::SolveMethod::PCR;//UsethePCRsolverinsteadofPCG.

//Createacompactcopyoftheright-handsideandallocatestorageforthesolution
TricyqleSolver::matrixb_solve{{.depth=num_blocks,.rows=block_size,.cols=1}};
matricesx{{.depth=num_blocks,.rows=block_size,.cols=1}};

//Callthesolverinparallel,passingalambdathatisexecutedbyeachthread.
autopctx=solver.create_parallel_context();
pctx->run([&](TricyqleSolver::Context&ctx){
//Copythedatatothesolver'sinternaldatastructures
usingfancyqlone::linalg::pack;
autopack_M=[&](index_ti,autoMs){returnpack(M.middle_batches(i,v,p),Ms);};
autopack_K=[&](index_ti,autoKs){returnpack(K.middle_batches(i,v,p),Ks);};
autopack_b=[&](index_ti,autobs){returnpack(b.middle_batches(i,v,p),bs);};
solver.init_diag(ctx,pack_M);
solver.init_subdiag(ctx,pack_K);
solver.init_rhs(ctx,b_solve,pack_b);
//Performthefactorizationandtheforwardsolve(fused),followedbythebackwardsolve
solver.factor_solve(ctx,b_solve);
solver.solve_reverse(ctx,b_solve);
//Copythesolutionbacktotheoriginallayout
usingfancyqlone::linalg::unpack;
autounpack_x=[&](index_ti,autoxs){returnunpack(xs,x.middle_batches(i,v,p));};
solver.get_solution(ctx,b_solve,unpack_x);
});//blocksuntilallthreadshavejoined

//Performafactorizationupdateandsolveagain
auto[B,F,S]=init_random_update(block_size,num_blocks,rank,circular);
matricesx2{{.depth=num_blocks,.rows=block_size,.cols=1}};
pctx->run([&](TricyqleSolver::Context&ctx){
usingfancyqlone::linalg::pack;
autopack_b=[&](index_ti,autobs){returnpack(b.middle_batches(i,v,p),bs);};
autopack_upd=[&](autoiS,autoSs,auto&sync_S,autoiB,autoBs,autoiF,autoFs){
pack(S.middle_batches(iS,v,p),Ss);//diagonalupdatematrix
sync_S();//indicatethatourpartofSisready(needstobeexchangedacrossthreads)
pack(B.middle_batches(iB,v,p),Bs);//diagonalblocksoftheupdatematrix
pack(F.middle_batches(iF,v,p),Fs);//subdiagonalblocksoftheupdatematrix
};
solver.init_update(ctx,rank,pack_upd);
solver.init_rhs(ctx,b_solve,pack_b);
solver.update_solve_cr(ctx,b_solve);
solver.solve_reverse(ctx,b_solve);
usingfancyqlone::linalg::unpack;
autounpack_x2=[&](index_ti,autoxs){returnunpack(xs,x2.middle_batches(i,v,p));};
solver.get_solution(ctx,b_solve,unpack_x2);
});

#ifCYQLONE_WITH_MATIO
//Exporttheoriginalsystemandthesolutionasa.matfile
std::filesystem::pathfilename="block_tridiagonal_system.mat";
automatfile=fancyqlone::create_mat(filename);
fancyqlone::add_to_mat(matfile.get(),"M",M);
fancyqlone::add_to_mat(matfile.get(),"K",K);
fancyqlone::add_to_mat(matfile.get(),"b",b);
fancyqlone::add_to_mat(matfile.get(),"x",x);
fancyqlone::add_to_mat(matfile.get(),"B",B);
fancyqlone::add_to_mat(matfile.get(),"F",F);
fancyqlone::add_to_mat(matfile.get(),"S",S);
fancyqlone::add_to_mat(matfile.get(),"x2",x2);
std::cout<<"Savedsystemandsolutionto"<<filename<<"\n";
#else
//Printtheoriginalsystemandthesolutioninaformatthat'seasytocheckusingPython
std::cout<<"importnumpyasnp\n";
std::cout<<"v="<<v<<"\n";
std::cout<<"n="<<block_size<<"\n";
std::cout<<"N="<<num_blocks<<"\n";
std::cout<<"M=np.array([\n";
for(index_ti=0;i<num_blocks;++i)
guanaqo::print_python(std::cout,M(i),",\n",false);
std::cout<<"])\nK=np.array([\n";
for(index_ti=0;i<num_blocks;++i)
guanaqo::print_python(std::cout,K(i),",\n",false);
std::cout<<"])\nb=np.array([\n";
for(index_ti=0;i<num_blocks;++i)
guanaqo::print_python(std::cout,b(i),",\n");
std::cout<<"])\nx=np.array([\n";
for(index_ti=0;i<num_blocks;++i)
guanaqo::print_python(std::cout,x(i),",\n");
std::cout<<"])\nB=np.array([\n";
for(index_ti=0;i<num_blocks;++i)
guanaqo::print_python(std::cout,B(i),",\n",false);
std::cout<<"])\nF=np.array([\n";
for(index_ti=0;i<num_blocks;++i)
guanaqo::print_python(std::cout,F(i),",\n",false);
std::cout<<"])\nS=np.array([\n";
for(index_ti=0;i<num_blocks;++i)
guanaqo::print_python(std::cout,S(i),",\n");
std::cout<<"])\nx2=np.array([\n";
for(index_ti=0;i<num_blocks;++i)
guanaqo::print_python(std::cout,x2(i),",\n");
std::cout<<"])\n";
#endif
}catch(std::exception&e){
std::cerr<<"Error:"<<e.what()<<"\n";
return1;
}

TridiagSysteminit_random_system(index_tblock_size,index_tnum_blocks,boolcircular){
usingbatmat::matrix::uninitialized;
std::mt19937rng(12345);
std::normal_distribution<real_t>dist(0.0,1.0);
//GeneratearandomlowerblockbidiagonalmatrixwithdiagonalblocksA(i)andsubdiagonal
//blocksB(i).
matricesA{{.depth=num_blocks,.rows=block_size,.cols=block_size},uninitialized};
matricesB{{.depth=num_blocks,.rows=block_size,.cols=block_size},uninitialized};
std::ranges::generate(A,[&]{returndist(rng);});
std::ranges::generate(B,[&]{returndist(rng);});
//Allocatestorageforablocktridiagonalsystem
matricesM{{.depth=num_blocks,.rows=block_size,.cols=block_size},uninitialized};
matricesK{{.depth=num_blocks,.rows=block_size,.cols=block_size},uninitialized};
matricesb{{.depth=num_blocks,.rows=block_size,.cols=1},uninitialized};
std::ranges::generate(b,[&]{returndist(rng);});
if(!circular)
B(num_blocks-1).set_constant(0);
//DiagonalblocksM(i)=A(i)A(i)ᵀ+B(i-1)B(i-1)ᵀandsubdiagonalblocksK(i)=B(i)A(i)ᵀ
for(index_ti=0;i<num_blocks;++i){
index_ti_prev=(i-1+num_blocks)%num_blocks;
guanaqo::blas::xsyrk_LN<real_t>(1,A(i),0,M(i));//M(i)=A(i)A(i)ᵀ
guanaqo::blas::xsyrk_LN<real_t>(1,B(i_prev),1,M(i));//M(i)+=B(i-1)B(i-1)ᵀ
guanaqo::blas::xgemm_NT<real_t>(1,B(i),A(i),0,K(i));//K(i)=B(i)A(i)ᵀ
M(i).add_to_diagonal(1e-4);//Ensurepositivedefiniteness
}
returnTridiagSystem{.M=std::move(M),.K=std::move(K),.b=std::move(b)};
}

BidiagUpdateinit_random_update(index_tblock_size,index_tnum_blocks,index_trank,
boolcircular){
usingbatmat::matrix::uninitialized;
std::mt19937rng(54321);
std::normal_distribution<real_t>dist(0.0,1.0);
//GeneratearandombidiagonalmatrixwithdiagonalblocksB(i)andsubdiagonalblocksF(i),as
//wellasrandomdiagonalmatricesΣ.
matricesB{{.depth=num_blocks,.rows=block_size,.cols=rank},uninitialized};
matricesF{{.depth=num_blocks,.rows=block_size,.cols=rank},uninitialized};
matricesS{{.depth=num_blocks,.rows=rank,.cols=1},uninitialized};
std::ranges::generate(B,[&]{returndist(rng);});
std::ranges::generate(F,[&]{returndist(rng);});
std::ranges::generate(S,[&]{returnstd::exp2(dist(rng));});
if(!circular)
F(num_blocks-1).set_constant(0);//Nocircularcoupling
returnBidiagUpdate{.B=std::move(B),.F=std::move(F),.S=std::move(S)};
}
